# -*- coding: utf-8 -*-
# HFSS (AEDT) IronPython script -- single G cell (6.4 mm rational-sector hub, 8 MADP diode sites), Floquet check. Generated by lwmom (Phase 28 HFSS-first path).
# MODEL_ONLY / NOT_HFSS_VALIDATED. Diode package inductance 0 nH (NOT_AVAILABLE_FROM_CURRENT_DATA, assumed zero).
# AEDT calls: VERIFIED in AEDT (3x3 smoke build, 2026-10-24): CreatePolyline sheets, Unite, AssignPerfectE, AssignLumpedRLC (ON: R only, OFF: C only, one element type per sheet), far-field sphere.
# Copied from the Phase 26 hex150 script (built the 150 mm board): substrate/ground/monopole/lumped port/radiation box/setup.
# NOT yet run in AEDT: AssignMaster/AssignSlave with a scan angle, AssignFloquetPort, EditLumpedRLC / DeleteBoundaries. Each is in a try/except that prints what to do by hand.
import ScriptEnv
ScriptEnv.Initialize("Ansoft.ElectronicsDesktop")
oDesktop.RestoreWindow()

def attrs(name, material, solve_inside, color="(255 128 0)", transp=0):
    return ["NAME:Attributes", "Name:=", name, "Flags:=", "", "Color:=", color, "Transparency:=", transp,
            "PartCoordinateSystem:=", "Global", "UDMId:=", "", "MaterialValue:=", '"' + material + '"',
            "SurfaceMaterialValue:=", '""', "SolveInside:=", solve_inside, "IsMaterialEditable:=", True,
            "UseMaterialAppearance:=", False, "IsLightweight:=", False]

def mm(v):
    return repr(float(v)) + "mm"

def poly_sheet(oEditor, name, pts, z, color="(255 128 0)"):
    pl = ["NAME:PolylineParameters", "IsPolylineCovered:=", True, "IsPolylineClosed:=", True,
          ["NAME:PolylinePoints"] + [["NAME:PLPoint", "X:=", mm(x), "Y:=", mm(y), "Z:=", z] for (x, y) in list(pts) + [pts[0]]],
          ["NAME:PolylineSegments"] + [["NAME:PLSegment", "SegmentType:=", "Line", "StartIndex:=", k, "NoOfPoints:=", 2] for k in range(len(pts))],
          ["NAME:PolylineXSection", "XSectionType:=", "None", "XSectionOrient:=", "Auto", "XSectionWidth:=", "0mm",
           "XSectionTopWidth:=", "0mm", "XSectionHeight:=", "0mm", "XSectionNumSegments:=", "0", "XSectionBendType:=", "Corner"]]
    oEditor.CreatePolyline(pl, attrs(name, "vacuum", True, color))

def rlc_args(name, on, line, z):
    # ON = R only, OFF = C only: one single-type Lumped RLC boundary per sheet (the AEDT-verified form)
    return ["NAME:" + name + "_RLC", "Objects:=", [name],
            ["NAME:CurrentLine", "Start:=", [mm(line[0][0]), mm(line[0][1]), z], "End:=", [mm(line[1][0]), mm(line[1][1]), z]],
            "RLC Type:=", "Parallel",
            "UseResist:=", bool(on), "Resistance:=", R_ON if on else "0ohm",
            "UseInduct:=", False, "Inductance:=", "0nH",
            "UseCap:=", (not on), "Capacitance:=", "0pF" if on else C_OFF]
STATE = 0                 # 0..3 = slot axis 0, 45, 90, 135 deg; change here, or run set_state.py on the built model
P = 6.4; H = 1.575; LID = 20.0
R_ON = "5.2ohm"; C_OFF = "0.025pF"
PIECES = {'hub': [[-1.2, -1.2], [1.2, -1.2], [1.2, 1.2], [-1.2, 1.2]], 'arm0': [[1.6, -0.6], [3.0, -1.3], [3.0, 1.3], [1.6, 0.6]], 'arm1': [[0.6, 1.6], [1.3, 3.0], [-1.3, 3.0], [-0.6, 1.6]], 'arm2': [[-1.6, 0.6], [-3.0, 1.3], [-3.0, -1.3], [-1.6, -0.6]], 'arm3': [[-0.6, -1.6], [-1.3, -3.0], [1.3, -3.0], [0.6, -1.6]], 'diag0': [[1.6, 1.0], [2.8, 1.6], [2.8, 2.8], [1.6, 2.8], [1.0, 1.6], [1.6, 1.6]], 'diag1': [[-1.0, 1.6], [-1.6, 2.8], [-2.8, 2.8], [-2.8, 1.6], [-1.6, 1.0], [-1.6, 1.6]], 'diag2': [[-1.6, -1.0], [-2.8, -1.6], [-2.8, -2.8], [-1.6, -2.8], [-1.0, -1.6], [-1.6, -1.6]], 'diag3': [[1.0, -1.6], [1.6, -2.8], [2.8, -2.8], [2.8, -1.6], [1.6, -1.0], [1.6, -1.6]]}
NECKS = [{'site': 0, 'corners': [[1.2, -0.2], [1.6, -0.2], [1.6, 0.2], [1.2, 0.2]], 'line': [[1.2, 0.0], [1.6, 0.0]]}, {'site': 1, 'corners': [[-0.2, 1.2], [0.2, 1.2], [0.2, 1.6], [-0.2, 1.6]], 'line': [[0.0, 1.2], [0.0, 1.6]]}, {'site': 2, 'corners': [[-1.6, -0.2], [-1.2, -0.2], [-1.2, 0.2], [-1.6, 0.2]], 'line': [[-1.6, 0.0], [-1.2, 0.0]]}, {'site': 3, 'corners': [[-0.2, -1.6], [0.2, -1.6], [0.2, -1.2], [-0.2, -1.2]], 'line': [[0.0, -1.6], [0.0, -1.2]]}, {'site': 4, 'corners': [[1.2, 1.0], [1.6, 1.0], [1.6, 1.2], [1.2, 1.2]], 'line': [[1.2, 1.1], [1.6, 1.1]]}, {'site': 5, 'corners': [[-1.2, 1.2], [-1.0, 1.2], [-1.0, 1.6], [-1.2, 1.6]], 'line': [[-1.1, 1.2], [-1.1, 1.6]]}, {'site': 6, 'corners': [[-1.6, -1.2], [-1.2, -1.2], [-1.2, -1.0], [-1.6, -1.0]], 'line': [[-1.6, -1.1], [-1.2, -1.1]]}, {'site': 7, 'corners': [[1.0, -1.6], [1.2, -1.6], [1.2, -1.2], [1.0, -1.2]], 'line': [[1.1, -1.6], [1.1, -1.2]]}]
STATE_ON = [[0, 2], [4, 6], [1, 3], [5, 7]]

oProject = oDesktop.NewProject()
oProject.InsertDesign("HFSS", "phase28_cell_G", "DrivenModal", "")
oDesign = oProject.SetActiveDesign("phase28_cell_G")
oEditor = oDesign.SetActiveEditor("3D Modeler")
import sys
def note(level, text):
    # print-only, never raises: a failed message must not stop the script
    try:
        oDesktop.AddMessage(oProject.GetName(), oDesign.GetName(), level, text)
    except Exception:
        pass
    try:
        sys.stdout.write(str(text) + "\n")
    except Exception:
        pass
oEditor.SetModelUnits(["NAME:Units Parameter", "Units:=", "mm", "Rescale:=", False])
oProject.GetDefinitionManager().AddMaterial(["NAME:RT5880_board", "CoordinateSystemType:=", "Cartesian",
    "BulkOrSurfaceType:=", 1, ["NAME:PhysicsTypes", "set:=", ["Electromagnetic"]],
    "permittivity:=", "2.2", "dielectric_loss_tangent:=", "0.0009"])
for n, v in (("scan_theta", "0deg"), ("scan_phi", "225deg")):
    oDesign.ChangeProperty(["NAME:AllTabs", ["NAME:LocalVariableTab", ["NAME:PropServers", "LocalVariables"],
        ["NAME:NewProps", ["NAME:" + n, "PropType:=", "VariableProp", "UserDef:=", True, "Value:=", v]]]])
Z = mm(H)
oEditor.CreateBox(["NAME:BoxParameters", "XPosition:=", mm(-P / 2), "YPosition:=", mm(-P / 2), "ZPosition:=", "0mm",
    "XSize:=", mm(P), "YSize:=", mm(P), "ZSize:=", Z], attrs("Substrate", "RT5880_board", True, "(0 128 0)", 0.6))
oEditor.CreateRectangle(["NAME:RectangleParameters", "IsCovered:=", True, "XStart:=", mm(-P / 2), "YStart:=", mm(-P / 2),
    "ZStart:=", "0mm", "Width:=", mm(P), "Height:=", mm(P), "WhichAxis:=", "Z"], attrs("Ground", "vacuum", True, "(128 128 128)"))
oEditor.CreateBox(["NAME:BoxParameters", "XPosition:=", mm(-P / 2), "YPosition:=", mm(-P / 2), "ZPosition:=", Z,
    "XSize:=", mm(P), "YSize:=", mm(P), "ZSize:=", mm(LID)], attrs("Air", "air", True, "(143 175 143)", 0.9))
names = []
for nm in sorted(PIECES):
    poly_sheet(oEditor, "M_" + nm, PIECES[nm], Z)
    names.append("M_" + nm)
oEditor.Unite(["NAME:Selections", "Selections:=", ",".join(names)], ["NAME:UniteParameters", "KeepOriginals:=", False])
oEditor.ChangeProperty(["NAME:AllTabs", ["NAME:Geometry3DAttributeTab", ["NAME:PropServers", names[0]],
    ["NAME:ChangedProps", ["NAME:Name", "Value:=", "Metal"]]]])
for k, nk in enumerate(NECKS):
    poly_sheet(oEditor, "D%d" % k, nk["corners"], Z, "(255 0 0)")
oBnd = oDesign.GetModule("BoundarySetup")
oBnd.AssignPerfectE(["NAME:PerfE_Ground", "Objects:=", ["Ground"], "InfGroundPlane:=", False])
oBnd.AssignPerfectE(["NAME:PerfE_Metal", "Objects:=", ["Metal"], "InfGroundPlane:=", False])
for k, nk in enumerate(NECKS):
    try:
        oBnd.AssignLumpedRLC(rlc_args("D%d" % k, k in STATE_ON[STATE], nk["line"], Z))
    except Exception as exc:
        note(2, "Lumped RLC D%d failed (%s): assign it by hand (one element type, current line along the neck, README)." % (k, str(exc)))

def one_face(body, x, y, z):
    # exactly one face id: AssignMaster / AssignSlave take one face each
    return int(oEditor.GetFaceByPosition(["NAME:FaceParameters", "BodyName:=", body, "XPosition:=", mm(x), "YPosition:=", mm(y), "ZPosition:=", mm(z)]))

# periodic walls: one master/slave pair PER FACE (substrate and air box separately), scan angle linked to the Floquet port. NOT yet run successfully in AEDT: if a pair fails the message names it,
# assign that pair by hand (README step 2).
for tag, body, z0, zc in (("s", "Substrate", 0.0, H / 2.0), ("a", "Air", H, H + LID / 2.0)):
    try:
        oBnd.AssignMaster(["NAME:MasterX" + tag, "Faces:=", [one_face(body, -P / 2, 0.0, zc)],
            "CoordSysVector:=", ["NAME:Vectors", "Origin:=", [mm(-P / 2), mm(-P / 2), mm(z0)], "UPos:=", [mm(-P / 2), mm(P / 2), mm(z0)]],
            "ReverseV:=", False])
        oBnd.AssignSlave(["NAME:SlaveX" + tag, "Faces:=", [one_face(body, P / 2, 0.0, zc)],
            "CoordSysVector:=", ["NAME:Vectors", "Origin:=", [mm(P / 2), mm(-P / 2), mm(z0)], "UPos:=", [mm(P / 2), mm(P / 2), mm(z0)]],
            "ReverseU:=", False, "Master:=", "MasterX" + tag, "UseScanAngle:=", True, "Phi:=", "scan_phi", "Theta:=", "scan_theta"])
    except Exception as exc:
        note(2, "Periodic X pair '" + tag + "' (" + body + ") failed (" + str(exc) + "): assign it by hand, README step 2.")
    try:
        oBnd.AssignMaster(["NAME:MasterY" + tag, "Faces:=", [one_face(body, 0.0, -P / 2, zc)],
            "CoordSysVector:=", ["NAME:Vectors", "Origin:=", [mm(-P / 2), mm(-P / 2), mm(z0)], "UPos:=", [mm(P / 2), mm(-P / 2), mm(z0)]],
            "ReverseV:=", False])
        oBnd.AssignSlave(["NAME:SlaveY" + tag, "Faces:=", [one_face(body, 0.0, P / 2, zc)],
            "CoordSysVector:=", ["NAME:Vectors", "Origin:=", [mm(-P / 2), mm(P / 2), mm(z0)], "UPos:=", [mm(P / 2), mm(P / 2), mm(z0)]],
            "ReverseU:=", False, "Master:=", "MasterY" + tag, "UseScanAngle:=", True, "Phi:=", "scan_phi", "Theta:=", "scan_theta"])
    except Exception as exc:
        note(2, "Periodic Y pair '" + tag + "' (" + body + ") failed (" + str(exc) + "): assign it by hand, README step 2.")
try:
    top = one_face("Air", 0.0, 0.0, H + LID)
    oBnd.AssignFloquetPort(["NAME:FloquetPort1", "Faces:=", [top], "NumModes:=", 2, "RenormalizeAllTerminals:=", True,
        "UseScanAngle:=", True, "Phi:=", "scan_phi", "Theta:=", "scan_theta", "DoDeembed:=", True, "DeembedDist:=", mm(LID),
        ["NAME:Modes", ["NAME:Mode1", "ModeNum:=", 1, "UseIntLine:=", False, "CharImp:=", "Zpi"],
                       ["NAME:Mode2", "ModeNum:=", 2, "UseIntLine:=", False, "CharImp:=", "Zpi"]],
        "ShowReporterFilter:=", False, "ReporterFilter:=", [True, True]])
except Exception as exc:
    note(2, "Floquet port assignment failed (" + str(exc) + "): assign it by hand on the top face of Air, 2 modes, de-embed " + mm(LID) + ", README step 2.")
oAna = oDesign.GetModule("AnalysisSetup")
oAna.InsertSetup("HfssDriven", ["NAME:Setup1", "Frequency:=", "10GHz", "MaxDeltaS:=", 0.01, "MaximumPasses:=", 15, "MinimumPasses:=", 2,
    "MinimumConvergedPasses:=", 2, "PercentRefinement:=", 30, "IsEnabled:=", True, "BasisOrder:=", 1, "DoLambdaRefine:=", True,
    "DoMaterialLambda:=", True, "SetLambdaTarget:=", False, "Target:=", 0.3333, "UseMaxTetIncrease:=", False])
oAna.InsertFrequencySweep("Setup1", ["NAME:Sweep", "IsEnabled:=", True, "RangeType:=", "LinearStep", "RangeStart:=", "9.5GHz", "RangeEnd:=", "10.5GHz",
    "RangeStep:=", "0.25GHz", "Type:=", "Discrete", "SaveFields:=", False, "SaveRadFields:=", False])
oEditor.FitAll()
oProject.SaveAs(oDesktop.GetProjectDirectory() + "/phase28_cell_G.aedt", True)
note(0, "Built state %d. Check the 8 RLC boundaries, the periodic pairs and the Floquet port, set scan_theta/scan_phi, Analyze." % STATE)
